import{crossFigure}from './gen-figures.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx=(x,y,s,n=17)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f7f3ed" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const line=(d,c='#b9cfce',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}"/>`;
const dot=(x,y,r=13,c='#e8ac97')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#ede0c5" stroke-width="2"/>`;
export const familySVG=(a,label)=>`<svg viewBox="0 0 560 440" role="img" aria-label="${esc(label)}">${a}</svg>`;
function person(x,y,id,sex,affected,genotype=''){let shape=sex==='square'?`<rect x="${x-23}" y="${y-23}" width="46" height="46" rx="4" fill="${affected?'#bf8b7b':'#35536b'}" stroke="#eadfce" stroke-width="3"/>`:`<circle cx="${x}" cy="${y}" r="23" fill="${affected?'#bf8b7b':'#35536b'}" stroke="#eadfce" stroke-width="3"/>`;return shape+tx(x,y-37,id,17)+tx(x,y+46,affected?'Affected':'Unaffected',14)+(genotype?tx(x,y+70,genotype,17):'');}
export function pedigreeFigure({people=[],fresh=false}={}){let a=tx(280,28,'Recessive model: affected phenotype = aa',21);a+=line('M195 116H365M280 116V210M160 210H400M160 210V251M400 210V251');a+=person(195,116,'I-1',fresh?'circle':'square',false,people[0])+person(365,116,'I-2',fresh?'square':'circle',false,people[1])+person(160,274,'II-1',fresh?'circle':'square',true,people[2])+person(400,274,'II-2',fresh?'square':'circle',false,people[3]);a+=tx(280,386,'Square: male · circle: female · filled + label: affected',13)+tx(280,418,'Fictional family · no genotypes implied by unfilled alone',13);return familySVG(a,'Fictional recessive pedigree: unaffected parents I-1 and I-2; affected offspring II-1 and unaffected II-2. Student genotype labels: '+people.map(v=>v||'blank').join(',')+'. Square male, circle female, filled means affected.');}
export function sexFigure({progress=.5}={}){let p=Math.max(0,Math.min(1,Number(progress)||0)),a=tx(280,28,'Typical XX × XY chromosome model',23);a+=`<rect x="60" y="70" width="160" height="55" rx="16" fill="#466478"/><rect x="340" y="70" width="160" height="55" rx="16" fill="#466478"/>`+tx(140,105,'Egg: X',22)+tx(420,105,'Sperm: X or Y',20);a+=line('M140 130L175 255M140 130L385 255M420 130L175 255M420 130L385 255');a+=dot(175,284,42,'#9abbb9')+dot(385,284,42,'#b28b80')+tx(175,293,'XX',27)+tx(385,293,'XY',27);for(let i=0;i<2;i++){let end=i?385:175,x=140+(end-140)*p,y=140+110*p;a+=dot(x,y,10,'#d6c09c');}a+=tx(175,355,'1/2 · 50%',19)+tx(385,355,'1/2 · 50%',19)+tx(280,401,'Alternative possible outcomes, not a birth sequence',14)+tx(280,430,'Simplified model · not every biological variation or identity',12);return familySVG(a,'An X egg can combine with X or Y sperm to form XX or XY in the standard model; each has probability50%. Animated paths show alternatives, not two embryos from one egg.');}
export function screeningFigure({kind='screening',state=''}={}){let a=tx(280,30,'Testing informs choices; outcomes remain uncertain',21);if(kind==='screening-data'){a+=tx(280,104,'Fictional classroom dataset · not a clinical rate',17);for(let i=0;i<8;i++){let x=100+i%4*120,y=178+Math.floor(i/4)*95;a+=dot(x,y,24,i<6?'#abc5bb':'#bb8f80')+tx(x,y+5,i<6?'N':'I',16);}a+=tx(280,348,'6 N: condition not identified · 2 I: identified',16)+tx(280,401,'Does not measure live births or all future health',15);}else{a+=`<rect x="42" y="92" width="216" height="180" rx="20" fill="#3c5c70" stroke="#aec6c3"/><rect x="300" y="92" width="216" height="180" rx="20" fill="#5b555e" stroke="#d5b6a4"/>`+tx(150,132,'Potential benefit',20)+tx(150,190,'Information on a',17)+tx(150,221,'specified condition',17)+tx(408,132,'Burdens / limits',20)+tx(408,190,'IVF, uncertainty,',17)+tx(408,221,'cost and access',17);a+=tx(280,327,'Different informed perspectives can remain',19)+tx(280,393,'Testing ≠ gene editing ≠ guaranteed healthy birth',16);}return familySVG(a,kind==='screening-data'?'Fictional eight-embryo dataset:6 without tested condition identified,2 with it identified. Not birth data.':'Compare potential reduction in transmission risk with IVF/testing burdens, limitations, access and ethical perspectives.');}
export function disorderFigure({state='carrier'}={}){let a=tx(280,30,'Two different inheritance models',23);a+=tx(150,100,'Polydactyly',22)+tx(150,153,'P dominant',21)+tx(150,209,'Pp: affected',19)+tx(150,254,'pp: unaffected',19);a+=line('M280 75V320');a+=tx(415,100,'Cystic fibrosis',22)+tx(415,153,'f recessive',21)+tx(415,209,'Ff: unaffected carrier',18)+tx(415,254,'ff: affected',19);a+=tx(280,355,'CF affects cell membranes',18)+tx(280,410,'Bounded GCSE examples · probability is per event',14);return familySVG(a,'Polydactyly: dominant P; Pp affected, pp unaffected. Cystic fibrosis: recessive f; Ff unaffected carrier, ff affected.');}
export function familyFigure(o={}){if(o.concealed)return familySVG(tx(280,215,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');if(o.kind==='pedigree')return pedigreeFigure(o);if(o.kind==='cross'||o.kind==='sex-grid')return crossFigure(o.kind==='sex-grid'?{rows:['X','X'],cols:['X','Y'],...o}:o);if(o.kind==='sex'||o.kind==='sex-process')return sexFigure(o);if(o.kind?.startsWith('screening'))return screeningFigure(o);if(o.kind==='disorders')return disorderFigure(o);return familySVG(tx(280,85,'One allele from each gamete',23)+tx(280,180,'Combine every row and column',21)+tx(280,275,'Count equally likely outcomes',21)+tx(280,385,'Probabilities do not impose a family quota',17),'Genetic probability principles: combine one allele from each parent; count all outcomes; events independent in the simple model.');}
export const familyAssessmentFigure=f=>pedigreeFigure({fresh:true}).replace('><', '><rect x="0" y="0" width="560" height="440" rx="16" fill="#1d3548"/><');
